class Solution:
    def numSquarefulPerms(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        used = [False] * n

        def is_sq(x):
            r = math.isqrt(x)
            return r * r == x

        def bt(pos, prev):
            if pos == n:
                return 1
            total = 0
            for i in range(n):
                if used[i] or (i > 0 and nums[i] == nums[i - 1] and not used[i - 1]):
                    continue
                if pos > 0 and not is_sq(nums[i] + prev):
                    continue
                used[i] = True
                total += bt(pos + 1, nums[i])
                used[i] = False
            return total

        return bt(0, -1)

