class Solution:
    def numSquarefulPerms(self, nums: List[int]) -> int:
        import math
        n = len(nums)
        adj = [[math.isqrt(nums[i] + nums[j]) ** 2 == nums[i] + nums[j]
                for j in range(n)] for i in range(n)]
        full = (1 << n) - 1
        dp = [[0] * n for _ in range(1 << n)]
        for i in range(n):
            if i == nums.index(nums[i]):
                dp[1 << i][i] = 1
        for mask in range(1 << n):
            for i in range(n):
                cur = dp[mask][i]
                if not cur:
                    continue
                for j in range(n):
                    if not (mask >> j) & 1 and adj[i][j]:
                        dp[mask | (1 << j)][j] += cur
        return sum(dp[full])

