class Solution {
public:
    int numSquarefulPerms(vector<int>& nums) {
        int n = nums.size();
        auto isSq = [](long long x) {
            long long r = (long long)sqrtl((long double)x);
            while (r * r > x) r--;
            while ((r + 1) * (r + 1) <= x) r++;
            return r * r == x;
        };
        vector<vector<bool>> adj(n, vector<bool>(n));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                adj[i][j] = isSq((long long)nums[i] + nums[j]);
        int full = (1 << n) - 1;
        vector<vector<long long>> dp(1 << n, vector<long long>(n, 0));
        for (int i = 0; i < n; i++) {
            bool first = true;
            for (int k = 0; k < i; k++) if (nums[k] == nums[i]) { first = false; break; }
            if (first) dp[1 << i][i] = 1;
        }
        for (int mask = 0; mask <= full; mask++)
            for (int i = 0; i < n; i++) {
                if (!dp[mask][i]) continue;
                for (int j = 0; j < n; j++)
                    if (!(mask >> j & 1) && adj[i][j])
                        dp[mask | (1 << j)][j] += dp[mask][i];
            }
        long long ans = 0;
        for (int i = 0; i < n; i++) ans += dp[full][i];
        return (int)ans;
    }
};

